				fontFamily: 'Helvetica',
				fontSize: 24,
				fill: 0xffffff,
				align: 'center',
				dropShadow: true,
				dropShadowBlur: 6,
				dropShadowDistance: 2,
				dropShadowAlpha: 0.5
