Game_MapFog.prototype.initialize = function(id) {
  this._id = id;
  this.name = '';
  this.opacity = 255;
  this.blendMode = 0;
  this.scaleX = 1;
  this.scaleY = 1;
  this.moveX = 0;
  this.moveY = 0;
  this.width = Graphics.width;
  this.height = Graphics.height;
  this.mapBind = true;
  this.visible = true;
  this.deactivateOnInvisible = true;
  this.active = true;  
  this.priority = 0;
  this.origin = new Point();
  this.move = new Point();
};
//=============================================================================
