Game_Character.prototype.getToolGraphic = function (shelfItem) {
    if (shelfItem === 0) {
        var x = 0;
        var y = 0;
    } else if (shelfItem === 10) {
        var x = 1;
        var y = 3;
    } else if (shelfItem === 3) {
        var x = 0;
        var y = 1;
    } else if (shelfItem === 4) {
        var x = 1;
        var y = 1;
    } else if (shelfItem === 6) {
        var x = 0;
        var y = 2;
    } else if (shelfItem === 7) {
        var x = 1;
        var y = 2;
    }
    return this.setCustomFrameXY(x, y);
}
