	//
	// BROWSER FIX: Font vertical positioning adjustment
	// The M+ font renders slightly higher in browser canvas vs NW.js.
	// Increase the cap-height ratio from 0.7 to 0.8 to shift text down ~1-2px.

	const _old_drawText = Bitmap.prototype.drawText;
	Bitmap.prototype.drawText = function(text, x, y, maxWidth, lineHeight, align) {
	    if (this._blockTextDrawing) { return; }
	    if (text !== undefined) {
	        var tx = x;
	        var ty = y + lineHeight - (lineHeight - this.fontSize * 0.8) / 2;
	        var context = this._context;
	        var alpha = context.globalAlpha;
	        maxWidth = maxWidth || 0xffffffff;
	        if (align === undefined) { align = 'left'; }
	        if (align === 'center') { tx += maxWidth / 2; }
	        if (align === 'right') { tx += maxWidth; }
	        context.save();
	        context.font = this._makeFontNameText();
			context.textAlign = align;
	        context.textBaseline = 'alphabetic';
	        context.globalAlpha = 1;
	        this._drawTextOutline(text, tx, ty, maxWidth);
	        context.globalAlpha = alpha;
	        this._drawTextBody(text, tx, ty, maxWidth);
	        context.restore();
	        this._baseTexture.update();
	    }
	};

	//###############################################################################
	//
	// BROWSER FIX: Define missing voidFilter references
	// VoidFilter was renamed to AlphaFilter in PIXI v4+

	if (typeof WindowLayer !== 'undefined' && !WindowLayer.voidFilter) {
		try {
			WindowLayer.voidFilter = new PIXI.filters.AlphaFilter();
		} catch(e) {
			WindowLayer.voidFilter = new PIXI.Filter();
		}
	}
	if (typeof Sprite !== 'undefined' && !Sprite.voidFilter) {
		try {
			Sprite.voidFilter = new PIXI.filters.AlphaFilter();
		} catch(e) {
			Sprite.voidFilter = new PIXI.Filter();
		}
	}

	//###############################################################################
	//
	// BROWSER FIX: Window padding/contents offset sync
	// Many OMORI windows override standardPadding() (e.g. return 4) but the
	// Window._refreshContents method positions the contents sprite using
	// this.padding (always 18). This desync shifts all text 14px right+down.
	// Fix: use standardPadding() for the contents sprite position instead.

	Window.prototype._refreshContents = function() {
		this._windowContentsSprite.move(this.standardPadding(), this.standardPadding());
	};

